"use client";
import { useRef, type ReactNode, type CSSProperties } from "react";
import { useScrollMotion, scrollUnits, scrollStage, type ScrollMotionProps } from "./scroll-shared";
export interface ParallaxLayer {
  id: string;
  content: ReactNode;
  speed: number;
  style?: CSSProperties;
  className?: string;
}
export interface ParallaxProps extends ScrollMotionProps {
  layers: readonly ParallaxLayer[];
  distance?: number;
  axis?: "x" | "y";
  children?: ReactNode;
}
export function Parallax({
  layers,
  distance = 160,
  axis = "y",
  children,
  ...props
}: ParallaxProps) {
  const root = useRef<HTMLDivElement>(null);
  useScrollMotion(
    root,
    props,
    ({ progress: p, reduced }) => {
      scrollUnits(root.current!).forEach((el, i) => {
        el.style.transform = `translate${axis.toUpperCase()}(${reduced ? 0 : (p - 0.5) * distance * layers[i]!.speed}px)`;
      });
    },
    `${layers.map((x) => x.id + ":" + x.speed).join(",")}:${distance}:${axis}`,
  );
  return (
    <div
      ref={root}
      data-scroll-animation="parallax"
      className={props.className}
      style={{ ...scrollStage, ...props.style }}
    >
      {layers.map((layer) => (
        <div
          key={layer.id}
          data-scroll-unit={layer.id}
          className={layer.className}
          style={{ position: "absolute", inset: 0, ...layer.style }}
        >
          {layer.content}
        </div>
      ))}
      {children}
    </div>
  );
}
